#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Minimal JSON token helpers for judge input ["s","p"]
typedef struct { char* s; int pos; int len; } Tok;
static void skipWS(Tok* t) { while (t->pos < t->len && (t->s[t->pos] == ' ' || t->s[t->pos] == ',' || t->s[t->pos] == '\t' || t->s[t->pos] == '\n' || t->s[t->pos] == '\r')) t->pos++; }
static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    if (t->s[t->pos] == '"') {
        t->pos++;
        int start = t->pos;
        while (t->pos < t->len && t->s[t->pos] != '"') t->pos++;
        int toklen = t->pos - start;
        char* out = (char*)malloc(toklen + 1);
        strncpy(out, t->s + start, toklen);
        out[toklen] = '\0';
        if (t->pos < t->len && t->s[t->pos] == '"') t->pos++;
        return out;
    }
    return NULL;
}

// DP solution: O(m*n) time, O(n) space
bool isMatch(const char* s, const char* p) {
    int m = (int)strlen(s);
    int n = (int)strlen(p);
    bool* dp = (bool*)calloc(n + 1, sizeof(bool));
    dp[n] = true; // dp at s suffix empty and p suffix empty
    // handle patterns like a*b*c* matching empty suffix
    for (int j = n - 2; j >= 0; --j) {
        if (p[j + 1] == '*') dp[j] = dp[j + 2];
    }
    for (int i = m - 1; i >= 0; --i) {
        bool prev = dp[n];
        dp[n] = false;
        for (int j = n - 1; j >= 0; --j) {
            bool cur = false;
            bool first_match = (p[j] == '.' || p[j] == s[i]);
            if (j + 1 < n && p[j + 1] == '*') {
                cur = dp[j + 2] || (first_match && dp[j]);
            } else {
                cur = first_match && prev;
            }
            prev = dp[j];
            dp[j] = cur;
        }
    }
    bool ans = dp[0];
    free(dp);
    return ans;
}

int main(void) {
    char *line = NULL; size_t cap = 0; ssize_t nread = getline(&line, &cap, stdin);
    if (nread <= 0) { if (line) free(line); return 0; }
    while (nread > 0 && (line[nread-1] == '\n' || line[nread-1] == '\r')) line[--nread] = '\0';
    Tok tok = { line, 0, (int)strlen(line) };
    char* s = nextToken(&tok);
    char* p = nextToken(&tok);
    bool res = isMatch(s ? s : "", p ? p : "");
    printf("%s\n", res ? "true" : "false");
    if (s) free(s); if (p) free(p); free(line);
    return 0;
}

